}

.toast-success {
    background: #198754;
}

.toast-error {
    background: #dc3545;
}

@keyframes toast-in {
    from {
        opacity: 0;
        transform: translateY(1rem);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}
